<?php\ndeclare(strict_types=1);\n\nabstract class AbstractReportBuilder\n{\n    protected string $title;\n    protected string $dateRange;\n    protected array $filters = [];\n\n    public function setTitle(string $title): self\n    {\n        $this->title = $title;\n        return $this;\n    }\n\n    public function setDateRange(string $dateRange): self\n    {\n        $this->dateRange = $dateRange;\n        return $this;\n    }\n\n    public function addFilter(string $filter): self\n    {\n        $this->filters[] = $filter;\n        return $this;\n    }\n\n    public function generate(): array\n    {\n        $data = $this->fetchData();\n        $this->validateData($data);\n        return $this->formatOutput($data);\n    }\n\n    abstract protected function fetchData(): array;\n    abstract protected function formatOutput(array $data): array;\n\n    protected function validateData(array $data): void\n    {\n        if (empty($this->title)) {\n            throw new \RuntimeException('Report title is required');\n        }\n        if (empty($this->dateRange)) {\n            throw new \RuntimeException('Date range is required');\n        }\n    }\n}\n